 19→func TestIsOutdated(t *testing.T) {
 20→	tests := []struct {
 21→		current string
 22→		latest  string
 23→		want    bool
 24→		desc    string
 25→	}{
 26→		// Standard semver cases
 27→		{"1.0.0", "1.0.1", true, "patch version bump"},
 28→		{"1.0.0", "1.1.0", true, "minor version bump"},
 29→		{"1.0.0", "2.0.0", true, "major version bump"},
 30→		{"1.0.1", "1.0.0", false, "current is newer"},
 31→		{"2.0.0", "1.9.9", false, "current major is higher"},
 32→		{"1.0.0", "1.0.0", false, "same version"},
 33→
 34→		// v-prefix handling
 35→		{"v1.0.0", "v1.0.1", true, "with v prefix"},
 36→		{"v1.0.0", "1.0.1", true, "mixed v prefix"},
 37→		{"1.0.0", "v1.0.1", true, "mixed v prefix reversed"},
 38→
 39→		// Pre-release versions (semver uses hyphen)
 40→		{"1.0.0-rc1", "1.0.0", true, "prerelease in current"},
 41→		{"1.0.0", "1.0.1-rc1", true, "prerelease in latest is still newer"},
 42→		{"1.0.0-dev-xxx", "1.0.1", false, "dev build skips version check"},
 43→	}
 44→
 45→	for _, tt := range tests {
 46→		t.Run(tt.desc, func(t *testing.T) {
 47→			got := isOutdated(tt.current, tt.latest)
 48→			if got != tt.want {
 49→				t.Errorf("isOutdated(%q, %q) = %v, want %v", tt.current, tt.latest, got, tt.want)
 50→			}
 51→		})
 52→	}
 53→}
